/* TraceVector: browser-local workspace. No GitHub write or live Splunk execution. */
'use strict';
const C=window.TV_CONTEXT, scenarios=window.TV_SCENARIOS;
const KEY='tracevector.workspace.v1';
const defaults=()=>({version:1,objectives:{},scenarioProgress:{},evidence:[],evidenceUpdates:{},docUpdates:{},proposals:[],detections:[],stig:{},activity:[],notes:''});
let state=defaults(), storageOK=true;
try{const stored=JSON.parse(localStorage.getItem(KEY)||'null');if(stored&&stored.version===1)state={...state,...stored};}catch(e){storageOK=false;}
let page=location.hash.slice(1)||'overview',currentScenario=null,step=0,selected=null,checked=false;
let evidenceFilter='all', evidenceSearch='',docSearch='',docFilter='all', detectionScenario='ssh';
const titles={overview:'Lab overview',objectives:'Lab objectives',scenarios:'Scenario lab',evidence:'Evidence & screenshots',remediation:'Remediation guidance',detections:'Detection studio',docs:'Project documentation',progress:'Your progress',review:'Review queue'};
const subtitles={overview:'A clearer picture of your lab. A stronger instinct for the hunt.',objectives:'Turn the documented lab into an evidence-backed learning path.',scenarios:'Follow the signal. Practice the reasoning behind every detection.',evidence:'Keep the proof close, the context clear, and your updates organized.',remediation:'Assess first. Propose a small change. Validate with evidence.',detections:'Develop a hypothesis, shape your SPL, and document what it proves.',docs:'The source of truth, organized around the work you are doing.',progress:'Track your practice and validation without overstating coverage.',review:'Prepare a concrete proposal before changing the repository.'};
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',flask:'<path d="M9 3h6m-5 0v6l-6 10a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3M7 14h10"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m21 15-5-5L5 21"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',book:'<path d="M12 5c-3-2-7-2-10 0v15c3-2 7-2 10 0 3-2 7-2 10 0V5c-3-2-7-2-10 0zm0 0v15"/>',chart:'<path d="M4 3v18h17M8 16v-4m5 4V7m5 9V4"/>',git:'<circle cx="6" cy="5" r="2"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="6" r="2"/><path d="M6 7v10m12-9c0 5-12 1-12 7"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',out:'<path d="M14 3h7v7m0-7L10 14m-1-9H4a1 1 0 0 0-1 1v14a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',file:'<path d="M14 2H5v20h14V7zm0 0v5h5M8 12h8m-8 4h8"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',server:'<rect x="3" y="3" width="18" height="7" rx="1"/><rect x="3" y="14" width="18" height="7" rx="1"/><path d="M6 6h1m-1 11h1"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v1"/>'};
function icon(name,size=16){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`;}
function esc(v){return String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));}
function ext(url,label,cls=''){return `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;}
function btn(label,action,cls='',ico){return `<button class="button ${cls}" data-action="${action}">${ico?icon(ico,14):''}${label}</button>`;}
function tag(text,cls=''){return `<span class="tag ${cls}">${esc(text)}</span>`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch(e){storageOK=false;toast('Browser storage is full or unavailable. Export a backup to preserve this session.');return false;}}
function log(text,type='file'){state.activity.unshift({text,type,time:new Date().toISOString()});state.activity=state.activity.slice(0,60);save();}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',4500);}
const nav=[['overview','Lab overview','grid'],['objectives','Lab objectives','target'],['scenarios','Scenario lab','flask'],['evidence','Evidence & screenshots','image'],['remediation','Remediation guidance','shield'],['detections','Detection studio','code'],['docs','Project documentation','book'],['progress','Progress tracking','chart'],['review','Review queue','git']];
const objectives=[{id:'architecture',title:'Understand the lab architecture',body:'Identify the RHEL-SPLUNK01, WINHUNT01 and RHEL-IDM01 roles, subnet and collection paths.',doc:3},{id:'collection',title:'Trace endpoint telemetry into Splunk',body:'Review Windows UF, Sysmon and Linux collection. Verify actual ingestion independently of configuration screenshots.',doc:0},{id:'network',title:'Validate the network-defense path',body:'Distinguish offline replay from live capture. VMnet8 does not automatically mirror peer traffic.',doc:4},{id:'hunt',title:'Practice a hypothesis-driven hunt',body:'Complete a guided scenario and record the evidence needed to validate its ATT&CK mapping.',doc:7},{id:'stig',title:'Build a RHEL 10 STIG evidence baseline',body:'Use the pinned benchmark metadata; capture read-only assessment evidence before any remediation.',doc:8},{id:'review',title:'Prepare a reviewable project update',body:'Describe proposed documentation or screenshot changes, validation, and rollback before a GitHub modification.',doc:14}];
function pct(){return Math.round(Object.values(state.objectives).filter(Boolean).length/objectives.length*100);}
function completeCount(){return scenarios.filter(s=>(state.scenarioProgress[s.id]||0)>=s.steps.length).length;}
function render(){if(!titles[page])page='overview';document.title=`TraceVector · ${titles[page]}`;const pending=state.proposals.filter(p=>p.status==='Awaiting review').length;document.getElementById('app').innerHTML=`<aside class="sidebar"><a class="brand" href="#overview"><span class="brandmark"><svg width="29" height="30" viewBox="0 0 30 30" fill="none" aria-hidden="true"><path d="m4 7 10 5L25 5M14 12v13M4 17l10 5 11-7" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><circle cx="4" cy="7" r="2" fill="currentColor"/><circle cx="25" cy="5" r="2" fill="currentColor"/></svg></span>TraceVector</a><div class="work-label">YOUR WORKSPACE</div><nav aria-label="Workspace">${nav.map(([id,label,ico])=>`<button class="nav-item ${page===id?'active':''}" ${page===id?'aria-current="page"':''} data-page="${id}">${icon(ico,17)}${label}${id==='review'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="repo-box"><b>${icon('git',13)} Review before GitHub</b><small>Proposals stay in your workspace.</small></div><div class="user"><span class="avatar">JB</span><div><b>James Banday</b><small>Personal lab workspace</small></div></div></div></aside><button class="mobile-shade" data-action="menu" aria-label="Close navigation"></button><main class="main"><header class="topbar"><button class="mobile-toggle" data-action="menu" aria-label="Open navigation">${icon('menu',20)}</button><div class="breadcrumb">Workspace <span>/</span> <b>${titles[page]}</b></div><div class="top-actions"><button class="search-launch" data-action="search" aria-label="Search workspace">${icon('search',16)}<span>Search workspace</span><kbd>Ctrl K</kbd></button><span class="local-chip"><i class="dot"></i> Browser-local</span><span class="avatar" style="height:28px;width:28px;font-size:9px">JB</span></div></header><div class="content"><div class="page-heading"><div><h1>${titles[page]}</h1><p class="subtitle">${subtitles[page]}</p></div><div class="heading-actions">${page==='overview'?btn('Export workspace','export','','download')+btn('Start a hunt','start-ssh','primary','plus'):page==='evidence'?btn('Add evidence','add-evidence','primary','plus'):page==='review'?btn('New proposal','add-proposal','primary','plus'):page==='progress'?btn('Export backup','export','primary','download'):page==='docs'?btn('Track an update','doc-update','primary','plus'):''}</div></div>${!storageOK?'<div class="notice warning">Browser storage is unavailable. Export a backup to keep your changes.</div>':''}<div id="page-body">${({overview:overview,objectives:objectivesPage,scenarios:scenariosPage,evidence:evidencePage,remediation:remediationPage,detections:detectionsPage,docs:docsPage,progress:progressPage,review:reviewPage})[page]()}</div><footer class="footer"><span>${icon('lock',11)} Private workspace · saved in this browser</span><span>RHEL 10 · Splunk · MITRE ATT&CK <span style="margin:0 5px">/</span> TraceVector</span></footer></div></main>`;}
function topology(){return `<svg viewBox="0 0 480 240" role="img" aria-label="Documented lab architecture: Windows and IdM send telemetry to Splunk on the 172.25.250.0/24 network"><defs><linearGradient id="flow"><stop stop-color="#8eab74" stop-opacity=".2"/><stop offset="1" stop-color="#bedc93"/></linearGradient></defs><path d="M128 73H228V120H293M128 177H228V120" fill="none" stroke="url(#flow)" stroke-width="1.4"/><path d="M125 73H228M125 177H228" stroke="#9eba82" stroke-width="1.3" stroke-dasharray="3 6"/><circle cx="228" cy="120" r="4" fill="#c8e898"/><g fill="#1b4437" stroke="#426148"><rect x="39" y="45" width="115" height="58" rx="7"/><rect x="39" y="149" width="115" height="58" rx="7"/><rect x="293" y="80" width="143" height="80" rx="8"/></g><g fill="none" stroke="#b4cf95" stroke-width="1.5"><rect x="54" y="60" width="20" height="15" rx="1"/><path d="M59 80h10m-5-5v5"/><rect x="54" y="164" width="20" height="7" rx="1"/><rect x="54" y="175" width="20" height="7" rx="1"/><path d="m312 103 10 7-10 7m15 0h10"/></g><g font-family="DM Sans,sans-serif"><text x="82" y="66" fill="#ebf4dd" font-size="9">WINHUNT01</text><text x="82" y="83" fill="#8eab8a" font-size="8">.20 · Windows 11</text><text x="82" y="170" fill="#ebf4dd" font-size="9">RHEL-IDM01</text><text x="82" y="187" fill="#8eab8a" font-size="8">.30 · Identity</text><text x="346" y="109" fill="#e2f2d0" font-size="12" font-weight="600">Splunk</text><text x="311" y="140" fill="#8eab8a" font-size="8">RHEL-SPLUNK01 · .10</text><text x="177" y="219" fill="#7d9f7d" font-size="8" letter-spacing="1">172.25.250.0/24</text></g></svg><div class="diagram-note">DOCUMENTED TOPOLOGY · NOT LIVE STATUS</div>`;}
function overview(){const s=scenarios.find(x=>(state.scenarioProgress[x.id]||0)<3)||scenarios[0],done=state.scenarioProgress[s.id]||0;return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><i class="dot" style="background:#c9e69c"></i> BUILD. OBSERVE. INVESTIGATE.</div><h2>Your lab. Your evidence.<br>Your next discovery.</h2><p>A hands-on workspace for network defense, RHEL hardening, and the art of threat hunting.</p>${btn('Explore the lab','go-objectives','lime','arrow')} ${ext(C.repoUrl,`${icon('git',12)} Source repository`,'button hero-source')}</div><div class="hero-diagram">${topology()}</div></section><section class="stats"><div class="stat"><div class="stat-title">LAB OBJECTIVES ${icon('target')}</div><div class="stat-value"><strong>${Object.values(state.objectives).filter(Boolean).length}<span style="font-size:17px;color:#bbc4b4"> / 6</span></strong></div><div class="mini-bar"><span style="width:${pct()}%"></span></div><div class="stat-footer">${pct()}% self-tracked completion</div></div><div class="stat"><div class="stat-title">EVIDENCE LIBRARY ${icon('image')}</div><div class="stat-value"><strong>${C.screenshots.length+state.evidence.length}</strong><span>items</span></div><div class="stat-footer">${C.screenshots.length} repository · ${state.evidence.length} local</div></div><div class="stat"><div class="stat-title">GUIDED SCENARIOS ${icon('flask')}</div><div class="stat-value"><strong>${completeCount()}<span style="font-size:17px;color:#bbc4b4"> / 3</span></strong></div><div class="stat-footer">Splunk + ATT&CK practice</div></div><div class="stat"><div class="stat-title">RHEL STIG BASELINE ${icon('shield')}</div><div class="stat-value"><strong>${Object.values(state.stig).filter(x=>x==='Captured locally').length}<span style="font-size:17px;color:#bbc4b4"> / 12</span></strong></div><div class="stat-footer">Local evidence tracking · scans pending</div></div></section><div class="grid-main"><section><div class="section-title"><h2>Your next investigation</h2><button class="text-link" data-page="scenarios">All scenarios ${icon('arrow',12)}</button></div><div class="panel scenario-feature"><div class="tags">${tag(s.difficulty,'mint')}${tag(s.technique)}${tag('Synthetic exercise')}</div><h3>${esc(s.title)}</h3><p>${esc(s.summary)}</p><div class="scenario-meta"><span>${icon('clock',12)} ${s.minutes} min</span><span>${icon('server',12)} RHEL 10 + Splunk</span><span>${icon('target',12)} ${s.tactic}</span></div><div class="scenario-foot"><div class="steps-dots">${s.steps.map((_,i)=>`<i class="${i<done?'done':''}"></i>`).join('')} <span style="margin-left:5px">${done} of 3 steps</span></div>${btn(done?'Continue scenario':'Start scenario',`start-${s.id}`,'primary','arrow')}</div></div></section><section><div class="section-title"><h2>Workspace activity</h2><button class="text-link" data-page="progress">View progress ${icon('arrow',12)}</button></div><div class="panel activity">${activityHTML(3)}</div></section></div><section><div class="section-title"><h2>From your evidence library <span style="color:#a5b09a;font-weight:400;font-size:10px;margin-left:5px">REPOSITORY SNAPSHOT</span></h2><button class="text-link" data-page="evidence">View all evidence ${icon('arrow',12)}</button></div><div class="evidence-grid">${[C.screenshots[8],C.screenshots[19],C.screenshots[21]].map((e)=>evidenceCard(e,C.screenshots.indexOf(e))).join('')}</div></section>`;}
function activityHTML(limit=20){const arr=state.activity.length?state.activity:[{text:'Repository context organized',type:'book',time:'',detail:'RHEL 10, Splunk, network defense & STIG'},{text:'27 screenshots indexed',type:'image',time:'',detail:'Existing repository assets · not test results'},{text:'Ready for your first investigation',type:'flask',time:'',detail:'Three guided, synthetic scenarios'}];return arr.slice(0,limit).map(a=>`<div class="activity-row"><span class="activity-icon">${icon(a.type,13)}</span><div><h4>${esc(a.text)}</h4><p>${esc(a.detail||'Saved in this browser')}</p></div><time>${a.time?esc(new Date(a.time).toLocaleDateString(undefined,{month:'short',day:'numeric'})):'Setup'}</time></div>`).join('');}
function objectivesPage(){return `<div class="notice">${icon('info')}These checkmarks track your own lab review. They do not certify deployment, detection coverage, or STIG compliance.</div><div class="panel">${objectives.map((o,i)=>`<div class="list-row"><input type="checkbox" data-objective="${o.id}" ${state.objectives[o.id]?'checked':''} aria-label="Mark ${esc(o.title)} complete"><div class="grow"><h3>${String(i+1).padStart(2,'0')} · ${o.title}</h3><p>${o.body}</p></div>${ext(C.docs[o.doc].url,`Read guide ${icon('out',12)}`,'button')}</div>`).join('')}</div><div class="two-col spaced"><div class="panel pad"><h2 class="small-title">The documented environment</h2><div class="data-scroll"><table class="data-table"><tr><th>Host</th><th>Address</th><th>Role</th></tr><tr><td>RHEL-SPLUNK01</td><td>172.25.250.10</td><td>Splunk / RHEL 10</td></tr><tr><td>WINHUNT01</td><td>172.25.250.20</td><td>Windows 11 endpoint</td></tr><tr><td>RHEL-IDM01</td><td>172.25.250.30</td><td>Identity services</td></tr></table></div><p class="hint">Documented configuration; this Site does not monitor host health. RHEL-SENSOR01 remains proposed.</p></div><div class="panel pad"><h2 class="small-title">Six core Splunk indexes</h2><div class="tags">${['win_security','win_system','powershell','sysmon','linux','lab'].map(x=>tag(x)).join('')}</div><p class="large-note spaced">Configuration is a starting point. Verify source, host, sourcetype, timestamps and event delivery before claiming a working detection.</p>${ext(C.docs[3].url,'Architecture reference ↗','text-link spaced')}</div></div>`;}
function scenariosPage(){if(currentScenario)return scenarioDetail();return `<div class="notice">${icon('flask')}A safe practice space: fixed synthetic records, guided reasoning, and immediate feedback. No live Splunk searches or host changes.</div><div class="scenario-cards">${scenarios.map((s,i)=>`<article class="panel"><div class="pad"><div class="between"><span class="scenario-number">INVESTIGATION 0${i+1}</span>${tag(s.difficulty)}</div><h3>${s.title}</h3><p>${s.summary}</p><div class="tags spaced">${tag(s.technique,'mint')}${tag(s.tactic)}</div><div class="scenario-meta"><span>${icon('clock',13)}${s.minutes} min</span><span>${state.scenarioProgress[s.id]||0} / 3 steps</span></div>${btn((state.scenarioProgress[s.id]||0)>=3?'Revisit scenario':state.scenarioProgress[s.id]?'Continue investigation':'Begin investigation',`start-${s.id}`,'primary','arrow')}</div></article>`).join('')}</div><div class="panel pad spaced"><h2 class="small-title">From practice to your lab</h2><p class="large-note">These examples use <code>index=tracevector_lab</code> and normalized training fields. Your repository uses six core indexes. Map each query to your actual data and confirm field extraction before using it in Splunk. An ATT&CK label is a hunting hypothesis, not validated coverage.</p><div class="source-links">${ext(C.docs[6].url,'Project ATT&CK mapping')}${ext(C.docs[7].url,'Hunt playbook')}</div></div>`;}
function scenarioDetail(){const s=scenarios.find(x=>x.id===currentScenario);if(step>=s.steps.length)return `<div class="panel completion">${icon('check',42)}<h2>Investigation complete.</h2><p>You worked through ${esc(s.title.toLowerCase())}, interpreted the evidence,<br>and tested a ${s.technique} hypothesis. Your practice progress is saved locally.</p>${btn('Explore another scenario','scenario-list','primary','arrow')}${btn('Draft a finding','scenario-finding','','file')}<p class="hint spaced">Practice completion does not establish live detection coverage.</p></div>`;const st=s.steps[step],cols=Object.keys(s.events[0]);return `<div class="between" style="margin-bottom:20px"><button class="text-link" data-action="scenario-list">${icon('back',14)} All investigations</button><div class="tags">${tag(s.technique,'mint')}${tag('Synthetic exercise')}</div></div><div class="scenario-detail"><section class="panel pad exercise"><div class="step-label">INVESTIGATION · STEP ${step+1} OF ${s.steps.length}</div><h2>${esc(st.title)}</h2><p>${esc(st.body)}</p><h3>${esc(st.question)}</h3>${st.options.map((o,i)=>`<button class="option ${selected===i?'selected':''}" data-answer="${i}" ${checked?'disabled':''}><span>${String.fromCharCode(65+i)}.</span>${esc(o)}</button>`).join('')}${checked?`<div class="feedback ${selected===st.answer?'':'wrong'}">${selected===st.answer?'Correct. ':`Review the evidence. The answer is ${String.fromCharCode(65+st.answer)}. `}${esc(st.explanation)}</div>`:''}<div class="between spaced">${step?btn('Previous step','prev-step','','back'):'<span></span>'}${checked?btn(selected===st.answer?(step===2?'Finish investigation':'Next step'):'Try again',selected===st.answer?'next-step':'retry-answer','primary','arrow'):`<button class="button primary" data-action="check-answer" ${selected===null?'disabled':''}>Check answer ${icon('check',14)}</button>`}</div></section><section class="stack"><div class="panel"><div class="pad"><h2 class="small-title">Evidence · ${s.events.length} training events</h2><p class="hint">${esc(s.logSource)}. Timestamps are fixture values.</p></div><div class="data-scroll"><table class="data-table"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${s.events.map(e=>`<tr>${cols.map(c=>`<td>${esc(e[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="panel pad"><div class="section-title"><h2>SPL to study</h2><button class="text-link" data-action="copy-scenario">${icon('copy',13)} Copy SPL</button></div><pre class="code">${esc(s.spl)}</pre><p class="hint">Reference query only. The browser does not run arbitrary SPL.</p><div class="source-links">${s.sources.map(x=>ext(x.url,esc(x.label))).join('')}</div></div></section></div>`;}
function evidenceCard(e,i,local=false){return `<button class="evidence-card" data-action="evidence-${local?'local-':''}${i}"><div class="thumb">${e.rawUrl?`<img src="${esc(e.rawUrl)}" alt="${esc(e.title)}" loading="lazy">`:icon(e.type==='Screenshot'?'image':'file',38)}${tag(local?'LOCAL EVIDENCE':'REPOSITORY ASSET')}</div><div class="evidence-info"><h3>${esc(e.title)}</h3><p>${icon(local?'file':'image',11)}${local?esc(e.type)+' · '+esc(new Date(e.created).toLocaleDateString()):esc(e.path.includes('network-defense-lab')?'Interface reference':'Lab documentation')}${(state.evidenceUpdates[e.path]||e.status)==='Needs update'?tag('Needs update','amber'):''}</p></div></button>`;}
function evidencePage(){let arr=C.screenshots.map((e,i)=>({...e,_i:i})),local=state.evidence.map((e,i)=>({...e,_i:i}));if(evidenceFilter==='local')arr=[];if(evidenceFilter==='repo')local=[];if(evidenceFilter==='updates'){arr=arr.filter(e=>state.evidenceUpdates[e.path]==='Needs update');local=local.filter(e=>e.status==='Needs update');}const match=e=>(e.title+' '+(e.path||'')+' '+(e.notes||'')).toLowerCase().includes(evidenceSearch.toLowerCase());arr=arr.filter(match);local=local.filter(match);return `<div class="notice">${icon('image')}Repository snapshot · ${C.snapshotDate} · ${C.screenshots.length} assets. Existing images are documentation, not proof of completed validation. Add sanitized evidence and flag screenshots that need an update.</div><div class="filterbar"><input class="field" id="evidence-search" placeholder="Search screenshots and evidence…" aria-label="Search evidence" value="${esc(evidenceSearch)}">${[['all','All evidence'],['repo','Repository'],['local','Local'],['updates','Needs update']].map(([id,label])=>`<button class="filter ${evidenceFilter===id?'active':''}" data-evidence-filter="${id}">${label}</button>`).join('')}</div><div class="evidence-grid">${local.map(e=>evidenceCard(e,e._i,true)).join('')}${arr.map(e=>evidenceCard(e,e._i)).join('')}</div>${!arr.length&&!local.length?'<div class="panel empty">No matching evidence. Add a record or choose another filter.</div>':''}`;}
function docCategory(d){return /stig/.test(d.path)?'stig':/mitre/.test(d.path)?'hunt':/network-defense|architecture|network-defense-validation/.test(d.path)?'network':'reference';}
function docsPage(){const arr=C.docs.filter(d=>(docFilter==='all'||docCategory(d)===docFilter)&&(d.title+' '+d.description+' '+d.path).toLowerCase().includes(docSearch.toLowerCase()));return `<div class="filterbar"><input class="field" id="doc-search" placeholder="Find a guide, playbook, or evidence checklist…" aria-label="Search documentation" value="${esc(docSearch)}">${[['all','All docs'],['network','Network defense'],['stig','STIG'],['hunt','Hunting']].map(([id,label])=>`<button class="filter ${docFilter===id?'active':''}" data-doc-filter="${id}">${label}</button>`).join('')}</div><div class="panel">${arr.map(d=>`<div class="list-row"><span class="icon-box">${icon(docCategory(d)==='stig'?'shield':'book',20)}</span><div class="grow"><h3>${esc(d.title)} ${(state.docUpdates[d.path]?.status)==='Needs update'?tag('Needs update','amber'):''}</h3><p>${esc(d.description)}</p><span class="doc-path">${esc(d.path)}</span></div><button class="button" data-doc="${C.docs.indexOf(d)}">Track</button>${ext(d.url,'Read source '+icon('out',13),'button')}</div>`).join('')||'<div class="empty">No documents found for this search.</div>'}</div><div class="notice spaced">${icon('git')}Source: ${ext(C.repoUrl,esc(C.repository))}. This is an organized snapshot, not a live GitHub sync. Documentation edits remain local proposals until you review and apply them separately.</div>`;}
function remediationPage(){const reqs=window.TV_STIG_REQUIREMENTS||Array.from({length:12},(_,i)=>({id:'stig-'+(i+1),title:'Evidence requirement '+(i+1),description:'See the repository RHEL STIG evidence checklist for the exact requirement.'}));return `<div class="notice warning">${icon('shield')}Current baseline: uploaded RHEL 10 STIG V1R1 inspected offline (396 rules). Live host scans and remediation have not been performed. Confirm the benchmark, release and applicable profile before assessing a host.</div><div class="two-col"><section><h2 class="small-title">A controlled remediation workflow</h2>${[{t:'01 · Assess without changing the host',p:'Record host identity, OS release, benchmark version and selected profile. Use the project’s read-only assessment workflow. Preserve the original result and note applicability.',doc:8},{t:'02 · Propose a minimal change',p:'Choose one rule or the smallest justified change set. Capture the current value, intended setting, affected services, exception rationale and rollback plan. Require review before repository changes.',doc:10},{t:'03 · Validate and retain the evidence',p:'After an approved change, rerun the applicable check. Test Splunk ingestion, identity services and authorized access. Compare before/after results; a screenshot alone does not prove compliance.',doc:11}].map((x,i)=>`<details ${i===0?'open':''}><summary>${x.t}</summary><p>${x.p}</p>${ext(C.docs[x.doc].url,'Open project guidance ↗','text-link')}</details>`).join('')}<div class="panel pad"><h3 class="small-title">Create a remediation proposal</h3><p class="large-note">Record the rule, evidence, test and rollback. Keep the change reviewable before anything reaches GitHub.</p>${btn('Draft a proposal','remediation-proposal','primary spaced','plus')}<div class="source-links">${ext(C.docs[9].url,'Benchmark metadata')}${ext(C.docs[12].url,'Windows 11 STIG')}${ext(C.docs[13].url,'Firewall STIG')}</div></div></section><section><div class="section-title"><h2>RHEL evidence checklist</h2>${tag('12 REQUIREMENTS')}</div><div class="panel">${reqs.map((r,i)=>`<div class="list-row" style="align-items:flex-start"><span class="icon-box" style="width:28px;height:28px;font-size:10px">${String(i+1).padStart(2,'0')}</span><div class="grow"><h3>${esc(r.title)}</h3><p style="font-size:10px">${esc(r.description)}</p><select class="field" style="font-size:10px;margin-top:8px;padding:5px 8px" data-stig="${r.id}" aria-label="${esc(r.title)} evidence status">${['Pending','In progress','Captured locally'].map(v=>`<option ${state.stig[r.id]===v?'selected':''}>${v}</option>`).join('')}</select></div></div>`).join('')}</div><p class="hint">Status is self-reported evidence tracking. “Captured locally” is not a compliance finding.</p></section></div>`;}
function detectionsPage(){const s=scenarios.find(x=>x.id===detectionScenario)||scenarios[0];return `<div class="notice">${icon('code')}Detection engineering workspace · practice with fixtures, then adapt to actual telemetry. Saved drafts stay in this browser and can be added to a review proposal.</div><div class="two-col"><section class="panel pad"><h2 class="small-title">Build a detection draft</h2><label class="label" for="detection-template">Start from a scenario</label><select id="detection-template" class="field">${scenarios.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${x.technique} · ${x.title}</option>`).join('')}</select><label class="label" for="detection-title">Detection name</label><input id="detection-title" class="field" value="${esc(s.title)}" maxlength="200"><label class="label" for="detection-spl">SPL</label><textarea id="detection-spl" class="field" style="font-family:Consolas;min-height:150px">${esc(s.spl)}</textarea><label class="label" for="detection-notes">Hypothesis, false positives & validation plan</label><textarea id="detection-notes" class="field" placeholder="Which behavior are you testing? Which legitimate activity could look similar? What would validate this hunt?"></textarea><div class="between spaced">${btn('Preview fixture','preview-fixture','','flask')}${btn('Save draft','save-detection','primary','check')}</div><p class="hint">Preview shows a fixed, labeled reference result for the selected template. It does not execute edited SPL.</p></section><section class="stack"><div class="panel pad"><div class="between"><h2 class="small-title">ATT&CK context</h2>${tag(s.technique,'mint')}</div><p class="large-note">${s.tactic} · candidate behavior</p><p class="hint">${esc(s.summary)} Corroborate with host context and independent evidence before claiming a detection.</p><div class="source-links">${s.sources.map(x=>ext(x.url,esc(x.label))).join('')}</div></div><div class="panel pad"><h2 class="small-title">Before this query reaches the lab</h2><p class="large-note">1. Map the training index to <code>linux</code> or the applicable project index.<br>2. Verify sourcetype and normalized fields.<br>3. Set a bounded time window and baseline.<br>4. Test benign and known-positive records.<br>5. Record false positives and coverage gaps.</p></div></section></div><section class="spaced"><div class="section-title"><h2>Saved detection drafts</h2>${tag(state.detections.length+' DRAFTS')}</div><div class="panel">${state.detections.map((d,i)=>`<div class="list-row"><span class="icon-box">${icon('code',18)}</span><div class="grow"><h3>${esc(d.title)} ${tag(d.technique)}</h3><p>${esc(d.notes||'Validation plan not yet recorded.')}</p></div><button class="button" data-detection="${i}">Open draft</button></div>`).join('')||'<div class="empty">Your first detection starts with a clear hypothesis. Save a draft above.</div>'}</div></section>`;}
function progressPage(){return `<div class="stats"><div class="stat"><div class="stat-title">OBJECTIVES</div><div class="progress-big">${pct()}<small> % complete</small></div><div class="mini-bar"><span style="width:${pct()}%"></span></div></div><div class="stat"><div class="stat-title">SCENARIOS</div><div class="progress-big">${completeCount()}<small> / 3 complete</small></div></div><div class="stat"><div class="stat-title">SCREENSHOT UPDATES</div><div class="progress-big">${Object.values(state.evidenceUpdates).filter(s=>s==='Needs update').length+state.evidence.filter(e=>e.status==='Needs update').length}<small> flagged</small></div></div><div class="stat"><div class="stat-title">DOCUMENTATION UPDATES</div><div class="progress-big">${Object.values(state.docUpdates).filter(s=>s?.status==='Needs update').length}<small> flagged</small></div></div></div><div class="two-col"><section class="stack"><div class="panel pad"><h2 class="small-title">Practice milestones</h2>${scenarios.map(s=>`<div style="margin:20px 0"><div class="between" style="font-size:12px"><span>${esc(s.title)}</span><span>${state.scenarioProgress[s.id]||0} / 3</span></div><div class="mini-bar"><span style="width:${(state.scenarioProgress[s.id]||0)/3*100}%"></span></div></div>`).join('')}</div><div class="panel pad"><h2 class="small-title">Lab journal</h2><p class="hint">Sanitized observations, questions and next steps. Saved when you click below.</p><textarea id="journal" class="field spaced" placeholder="What did you learn? What evidence is still missing?" style="min-height:140px" maxlength="20000">${esc(state.notes)}</textarea>${btn('Save journal','save-journal','primary spaced','check')}</div><div class="panel pad"><h2 class="small-title">Keep your workspace portable</h2><p class="large-note">Progress, notes, drafts and local evidence are stored on this browser and device. Export a JSON backup to move your work or keep a copy.</p><div class="heading-actions spaced">${btn('Export backup','export','','download')}${btn('Import backup','import','','file')}</div><input type="file" id="backup-import" class="hidden" accept="application/json"></div></section><section><h2 class="small-title">Activity log</h2><div class="panel activity">${activityHTML()}</div></section></div>`;}
function reviewPage(){return `<div class="notice">${icon('lock')}Human review is required before modifying the GitHub repository. This Site records proposals and review decisions locally. It cannot push, commit, open a PR, or apply host changes.</div><div class="stack">${state.proposals.map((p,i)=>`<article class="panel review-item"><div class="between"><div class="tags">${tag(p.type)}${tag(p.status,p.status==='Awaiting review'?'amber':'mint')}</div><span class="hint">${esc(new Date(p.created).toLocaleDateString())}</span></div><h3>${esc(p.title)}</h3><div class="doc-path">${esc(p.path||'Path to be determined')}</div><pre class="code spaced">${esc(p.body)}</pre><div class="between spaced"><span class="hint">Review decision does not modify GitHub.</span><div class="heading-actions">${btn('Open & review',`proposal-${i}`,'primary','git')}${btn('Export proposal',`export-proposal-${i}`,'','download')}</div></div></article>`).join('')||`<div class="panel empty">${icon('git',32)}<h2 style="font-size:19px;margin:18px 0 7px">Good changes start with a clear proposal.</h2><p>Draft a documentation update, screenshot refresh, detection, or remediation plan.</p>${btn('Create your first proposal','add-proposal','primary spaced','plus')}</div>`}</div><div class="source-links">${ext(C.repoUrl,'Open source repository')}${ext(C.existingSiteUrl,'Original network-defense workbench')}</div>`;}
function modal(html){const d=document.getElementById('modal');d.innerHTML=html;d.setAttribute('aria-label',d.querySelector('h2')?.textContent||'TraceVector dialog');if(!d.open)d.showModal();}
function modalHead(title){return `<div class="dialog-head"><h2>${esc(title)}</h2><button class="close" data-action="close-modal" aria-label="Close dialog">${icon('close',16)}</button></div>`;}
function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);}
async function openEvidence(i,local=false){const e=local?state.evidence[i]:C.screenshots[i];if(!e)return;let file=null;if(local&&e.fileId){try{file=await dbGet(e.fileId);}catch{}}modal(`${modalHead(e.title)}${!local?`<img src="${esc(e.rawUrl)}" alt="${esc(e.title)}">`:file?.data&&file.mime.startsWith('image/')?`<img src="${file.data}" alt="${esc(e.title)}">`:''}<p class="doc-path spaced">${esc(e.path||e.filename||'Local evidence record')}</p><p class="hint">${local?'Added '+esc(new Date(e.created).toLocaleString()):'Existing repository asset · snapshot '+C.snapshotDate+'. Not a completed test result.'}</p><label class="label" for="evidence-status">Update status</label><select class="field" id="evidence-status"><option>Current reference</option><option>Needs update</option><option>Replacement ready locally</option></select><label class="label" for="evidence-note">Update notes / capture context</label><textarea id="evidence-note" class="field" placeholder="Host, capture time, objective, what needs updating…" maxlength="5000">${esc(local?e.notes:state.evidenceUpdates[e.path+'::notes']||'')}</textarea><div class="modal-actions">${!local?ext(e.url,'View source ↗','button'):file?btn('Download file',`download-evidence-${i}`,'','download'):''}${btn('Save tracking',`save-evidence-${local?'local-':''}${i}`,'primary','check')}</div>`);document.getElementById('evidence-status').value=local?e.status||'Current reference':state.evidenceUpdates[e.path]||'Current reference';}
function addEvidence(){modal(`${modalHead('Add lab evidence')}<form id="evidence-form"><label class="label" for="e-title">Evidence title</label><input id="e-title" class="field" required maxlength="200" placeholder="RHEL-SPLUNK01 · ingestion validation"><label class="label" for="e-type">Type</label><select id="e-type" class="field"><option>Screenshot</option><option>Assessment output</option><option>Hunt notes</option><option>Documentation</option></select><label class="label" for="e-file">Attach a sanitized file (optional, up to 8 MB)</label><input type="file" id="e-file" class="field" accept="image/png,image/jpeg,image/webp,text/plain,text/markdown,application/pdf,.log,.csv,.json"><label class="label" for="e-notes">Host, timestamp, objective & observations</label><textarea id="e-notes" class="field" maxlength="5000" placeholder="Record enough context for someone else to review the evidence."></textarea><p class="hint">Stored in this browser. Export backups include attached files. Review for secrets and personal data before adding or sharing evidence.</p><div class="modal-actions"><button class="button primary" type="submit">Save evidence</button></div></form>`);}
function openDoc(i){const d=C.docs[i],u=state.docUpdates[d.path]||{};modal(`${modalHead('Track documentation update')}<h3 class="small-title">${esc(d.title)}</h3><p class="doc-path">${esc(d.path)}</p><label class="label" for="doc-status">Status</label><select id="doc-status" class="field">${['Current reference','Needs update','Draft ready locally'].map(s=>`<option ${u.status===s?'selected':''}>${s}</option>`).join('')}</select><label class="label" for="doc-note">What should change?</label><textarea id="doc-note" class="field" maxlength="5000">${esc(u.notes||'')}</textarea><div class="modal-actions">${ext(d.url,'Read source ↗','button')}${btn('Create proposal',`doc-proposal-${i}`,'','git')}${btn('Save tracking',`save-doc-${i}`,'primary','check')}</div>`);}
function proposalForm(prefill={},i=null){const p=i===null?prefill:state.proposals[i];modal(`${modalHead(i===null?'Draft a proposed change':'Review proposed change')}<form id="proposal-form" data-index="${i===null?'':i}"><label class="label" for="p-title">Title</label><input id="p-title" class="field" required maxlength="200" value="${esc(p.title||'')}"><label class="label" for="p-type">Change type</label><select id="p-type" class="field">${['Documentation','Screenshot update','Detection','Remediation'].map(v=>`<option ${p.type===v?'selected':''}>${v}</option>`).join('')}</select><label class="label" for="p-path">Proposed repository path</label><input id="p-path" class="field" maxlength="500" value="${esc(p.path||'')}"><label class="label" for="p-body">Proposed content, evidence, validation & rollback</label><textarea id="p-body" class="field" style="min-height:190px" required maxlength="30000">${esc(p.body||'Proposed change:\n\nReason and supporting evidence:\n\nValidation plan:\n\nRollback / recovery:\n')}</textarea><label class="label" for="p-status">Local review decision</label><select id="p-status" class="field">${['Awaiting review','Reviewed — ready for manual application','Changes requested','Deferred'].map(v=>`<option ${p.status===v?'selected':''}>${v}</option>`).join('')}</select><p class="hint">This records your review decision only. Apply any approved GitHub change separately after reviewing the exact content.</p><div class="modal-actions"><button class="button primary" type="submit">${i===null?'Save proposal':'Save review'}</button></div></form>`);}
function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
let dbPromise;
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('tracevector-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});return dbPromise;}
async function dbOp(mode,run){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('files',mode),req=run(tx.objectStore('files'));let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
const dbGet=id=>dbOp('readonly',o=>o.get(id));const dbPut=value=>dbOp('readwrite',o=>o.put(value));
async function exportWorkspace(){let files=[];try{files=(await dbOp('readonly',o=>o.getAll())).filter(f=>state.evidence.some(e=>e.fileId===f.id));}catch(e){if(state.evidence.some(x=>x.fileId))throw Error('Evidence files could not be read; backup was not exported.');}download('tracevector-workspace.json',JSON.stringify({app:'TraceVector',version:1,exported:new Date().toISOString(),repository:C.repository,state,files},null,2));toast('Workspace backup exported, including local attachments.');}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{modal(`${modalHead('Copy this text')}<textarea class="field" rows="12" readonly>${esc(text)}</textarea>`);}}
function goto(id){currentScenario=null;page=id;location.hash=id;render();window.scrollTo(0,0);}
function fixturePreview(){const s=scenarios.find(x=>x.id===detectionScenario),result=s.id==='ssh'?[{src_ip:'192.0.2.44',host:'rhel10-lab',failures:5,users:'admin, root'}]:s.id==='sudo'?[{host:'rhel10-lab',user:'analyst',run_as:'root',executions:1,commands:'/usr/bin/systemctl status sshd'},{host:'rhel10-lab',user:'labuser',run_as:'root',executions:2,commands:'/usr/bin/bash, /usr/bin/id'}]:[{host:'rhel10-lab',resource:'/etc/cron.d/telemetry-test',events:4,actions:'created, executed',users:'labuser, root'}];const cols=Object.keys(result[0]);modal(`${modalHead('Reference fixture result')}<div class="notice">Fixed output for “${s.title}”. This is an illustrative result for the original template. Edited SPL is not executed.</div><pre class="code">${esc(s.spl)}</pre><div class="data-scroll spaced"><table class="data-table"><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr>${result.map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')}</table></div>`);}
function searchModal(){modal(`${modalHead('Search your workspace')}<input class="field" id="global-search" autofocus placeholder="Try STIG, Splunk, screenshots, or SSH…" aria-label="Search workspace"><div class="search-results" id="search-results"></div>`);document.getElementById('global-search').focus();}
function searchResults(q){const results=[...nav.map(([id,title])=>({title,kind:'Section',action:'go-'+id})),...C.docs.map((d,i)=>({title:d.title+' · '+d.description,kind:'Guide',action:'find-doc-'+i})),...scenarios.map(s=>({title:s.title+' · '+s.technique,kind:'Scenario',action:'start-'+s.id})),...C.screenshots.map((s,i)=>({title:s.title,kind:'Screenshot',action:'evidence-'+i}))].filter(x=>x.title.toLowerCase().includes(q.toLowerCase())).slice(0,15);document.getElementById('search-results').innerHTML=q.trim()?results.map(r=>`<button class="search-result" data-action="${r.action}">${tag(r.kind)}${esc(r.title)}</button>`).join('')||'<div class="empty">No matching items.</div>':'<p class="hint">Search sections, project guides, scenarios and repository screenshots.</p>';}
document.addEventListener('click',async e=>{const pageButton=e.target.closest('[data-page]');if(pageButton){goto(pageButton.dataset.page);return;}const answer=e.target.closest('[data-answer]');if(answer){selected=Number(answer.dataset.answer);render();return;}const ef=e.target.closest('[data-evidence-filter]');if(ef){evidenceFilter=ef.dataset.evidenceFilter;render();return;}const df=e.target.closest('[data-doc-filter]');if(df){docFilter=df.dataset.docFilter;render();return;}const doc=e.target.closest('[data-doc]');if(doc){openDoc(Number(doc.dataset.doc));return;}const det=e.target.closest('[data-detection]');if(det){const i=Number(det.dataset.detection),d=state.detections[i];modal(`${modalHead(d.title)}${tag(d.technique)}<pre class="code spaced">${esc(d.spl)}</pre><p class="large-note spaced">${esc(d.notes||'No validation notes yet.')}</p><div class="modal-actions">${btn('Copy SPL',`copy-detection-${i}`,'','copy')}${btn('Create proposal',`detection-proposal-${i}`,'primary','git')}</div>`);return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{if(a==='menu'){document.querySelector('.sidebar').classList.toggle('open');return;}if(a==='close-modal'){document.getElementById('modal').close();return;}if(a==='search'){searchModal();return;}if(a.startsWith('go-')){document.getElementById('modal').close();goto(a.slice(3));return;}if(a.startsWith('start-')){document.getElementById('modal').close();currentScenario=a.slice(6);step=Math.min(state.scenarioProgress[currentScenario]||0,2);selected=null;checked=false;page='scenarios';location.hash='scenarios';render();window.scrollTo(0,0);return;}if(a==='scenario-list'){currentScenario=null;render();return;}if(a==='check-answer'){if(selected===null)return;checked=true;render();return;}if(a==='retry-answer'){checked=false;selected=null;render();return;}if(a==='next-step'){if(!checked||selected!==scenarios.find(s=>s.id===currentScenario).steps[step].answer)return;state.scenarioProgress[currentScenario]=Math.max(state.scenarioProgress[currentScenario]||0,step+1);if(step===2)log('Completed '+scenarios.find(s=>s.id===currentScenario).title,'flask');else save();step++;selected=null;checked=false;render();window.scrollTo(0,0);return;}if(a==='prev-step'){step--;selected=null;checked=false;render();return;}if(a==='copy-scenario'){await copy(scenarios.find(s=>s.id===currentScenario).spl);return;}if(a==='scenario-finding'){const s=scenarios.find(s=>s.id===currentScenario);proposalForm({title:s.title+' · practice finding',type:'Detection',body:`Synthetic exercise: ${s.title}\nATT&CK hypothesis: ${s.technique}\n\nReference SPL:\n${s.spl}\n\nObserved evidence: synthetic fixture only; not live lab coverage.\n\nNext validation steps:\nMap fields and index; test against approved lab data.\n\nRollback: documentation-only proposal.`});return;}if(a==='add-evidence'){addEvidence();return;}if(a.startsWith('save-evidence-')){const local=a.includes('local-'),i=Number(a.replace('save-evidence-','').replace('local-','')),status=document.getElementById('evidence-status').value,notes=document.getElementById('evidence-note').value;if(local){state.evidence[i].status=status;state.evidence[i].notes=notes;state.evidence[i].updated=new Date().toISOString();}else{state.evidenceUpdates[C.screenshots[i].path]=status;state.evidenceUpdates[C.screenshots[i].path+'::notes']=notes;}log('Updated evidence tracking','image');document.getElementById('modal').close();render();toast('Evidence tracking saved locally.');return;}if(a.startsWith('evidence-')){const local=a.includes('local-');await openEvidence(Number(a.replace('evidence-','').replace('local-','')),local);return;}if(a.startsWith('download-evidence-')){const d=await dbGet(state.evidence[Number(a.slice(18))].fileId);if(d){const link=document.createElement('a');link.href=d.data;link.download=d.name;link.click();}return;}if(a==='doc-update'){const d=C.docs.findIndex(d=>state.docUpdates[d.path]?.status==='Needs update');openDoc(d<0?0:d);return;}if(a.startsWith('find-doc-')){document.getElementById('modal').close();goto('docs');openDoc(Number(a.slice(9)));return;}if(a.startsWith('save-doc-')||a.startsWith('doc-proposal-')){const i=Number(a.split('-').pop()),d=C.docs[i],notes=document.getElementById('doc-note').value;state.docUpdates[d.path]={status:document.getElementById('doc-status').value,notes,updated:new Date().toISOString()};log('Tracked documentation: '+d.title,'book');if(a.startsWith('doc-proposal-'))proposalForm({title:'Update '+d.title,path:d.path,type:'Documentation',body:`Proposed update:\n${notes}\n\nSupporting evidence:\n\nValidation plan:\n\nRollback / recovery:\n`});else{document.getElementById('modal').close();render();toast('Documentation tracking saved locally.');}return;}if(a==='remediation-proposal'){proposalForm({type:'Remediation',title:'RHEL 10 STIG · proposed rule remediation',path:'docs/stig-rhel10/03-remediation-and-exceptions.md',body:'Benchmark and rule ID:\n\nHost / applicability:\n\nRead-only assessment evidence:\n\nProposed minimal change:\n\nImpact on Splunk, access and IdM:\n\nValidation / retest:\n\nBackup and rollback:\n\nExceptions / reviewer decision:\n'});return;}if(a==='add-proposal'){proposalForm();return;}if(a.startsWith('proposal-')){proposalForm({},Number(a.slice(9)));return;}if(a.startsWith('export-proposal-')){const p=state.proposals[Number(a.slice(16))];download('tracevector-proposal.md',`# ${p.title}\n\nType: ${p.type}\nPath: ${p.path}\nReview: ${p.status}\n\n${p.body}\n\n---\nLocal proposal only. No GitHub changes applied.\n`,'text/markdown');return;}if(a==='preview-fixture'){fixturePreview();return;}if(a==='save-detection'){const title=document.getElementById('detection-title').value.trim(),spl=document.getElementById('detection-spl').value.trim();if(!title||!spl){toast('Add a detection name and SPL before saving.');return;}state.detections.unshift({id:uid(),title,spl,notes:document.getElementById('detection-notes').value,technique:scenarios.find(x=>x.id===detectionScenario).technique,created:new Date().toISOString()});log('Saved detection draft: '+title,'code');render();toast('Detection draft saved locally.');return;}if(a.startsWith('copy-detection-')){await copy(state.detections[Number(a.slice(15))].spl);return;}if(a.startsWith('detection-proposal-')){const d=state.detections[Number(a.slice(19))];proposalForm({title:d.title,type:'Detection',body:`ATT&CK hypothesis: ${d.technique}\n\nProposed SPL:\n${d.spl}\n\nHypothesis / false positives / validation:\n${d.notes}\n\nActual index and field mapping:\n\nRollback / recovery:\n`});return;}if(a==='save-journal'){state.notes=document.getElementById('journal').value;log('Updated lab journal','book');toast('Journal saved locally.');return;}if(a==='export'){await exportWorkspace();return;}if(a==='import'){document.getElementById('backup-import').click();return;}if(a==='confirm-import'){await applyImport();return;}}catch(err){toast('Could not complete this action. '+err.message);}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.objective){state.objectives[el.dataset.objective]=el.checked;log((el.checked?'Completed review: ':'Reopened: ')+objectives.find(x=>x.id===el.dataset.objective).title,'target');render();}if(el.dataset.stig){state.stig[el.dataset.stig]=el.value;log('RHEL evidence status: '+el.value,'shield');toast('Evidence status saved locally; no compliance claim.');}if(el.id==='detection-template'){detectionScenario=el.value;render();}if(el.id==='backup-import'&&el.files[0]){try{const f=el.files[0];if(f.size>100*1024*1024)throw Error('Backup exceeds 100 MB.');const backup=JSON.parse(await f.text());validateBackup(backup);window.pendingBackup=backup;modal(`${modalHead('Import workspace backup')}<p class="large-note">Replace this browser’s tracking, progress and drafts with the selected TraceVector backup? It contains ${backup.state.evidence.length} evidence records and ${backup.state.proposals.length} proposals.</p><p class="hint">Export the current workspace first if you need to preserve it. The GitHub repository is unaffected.</p><div class="modal-actions">${btn('Cancel','close-modal')}${btn('Replace local workspace','confirm-import','primary')}</div>`);}catch(err){toast('Import rejected: '+err.message);}el.value='';}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='global-search')searchResults(el.value);if(el.id==='evidence-search'){evidenceSearch=el.value;const pos=el.selectionStart;document.getElementById('page-body').innerHTML=evidencePage();const n=document.getElementById('evidence-search');n.focus();n.setSelectionRange(pos,pos);}if(el.id==='doc-search'){docSearch=el.value;const pos=el.selectionStart;document.getElementById('page-body').innerHTML=docsPage();const n=document.getElementById('doc-search');n.focus();n.setSelectionRange(pos,pos);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;try{if(form.id==='evidence-form'){const title=document.getElementById('e-title').value.trim();if(!title)return;const f=document.getElementById('e-file').files[0];let fileId=null;if(f){if(f.size>8*1024*1024)throw Error('Please select a file under 8 MB.');const allowed=/^(image\/(png|jpeg|webp)|text\/|application\/(pdf|json))/;if(f.type&&!allowed.test(f.type))throw Error('Choose an image, text, JSON or PDF file.');const usedFiles=(await dbOp('readonly',o=>o.getAll())).filter(x=>state.evidence.some(e=>e.fileId===x.id));if(usedFiles.reduce((n,x)=>n+x.data.length,0)+f.size*1.34>90*1024*1024)throw Error('The local evidence budget is 90 MB. Use smaller files to keep backups portable.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(f);});fileId=uid();await dbPut({id:fileId,name:f.name,mime:f.type||'application/octet-stream',data});}state.evidence.unshift({id:uid(),title,type:document.getElementById('e-type').value,notes:document.getElementById('e-notes').value,fileId,filename:f?.name||'',created:new Date().toISOString(),status:'Current reference'});log('Added evidence: '+title,'image');document.getElementById('modal').close();render();toast('Evidence saved in this browser.');}if(form.id==='proposal-form'){const old=form.dataset.index===''?null:Number(form.dataset.index),p={id:old===null?uid():state.proposals[old].id,title:document.getElementById('p-title').value.trim(),type:document.getElementById('p-type').value,path:document.getElementById('p-path').value.trim(),body:document.getElementById('p-body').value,status:document.getElementById('p-status').value,created:old===null?new Date().toISOString():state.proposals[old].created,updated:new Date().toISOString()};if(!p.title||!p.body.trim())return;if(old===null)state.proposals.unshift(p);else state.proposals[old]=p;log((old===null?'Drafted proposal: ':'Recorded review: ')+p.title,'git');document.getElementById('modal').close();render();toast('Saved locally. No GitHub changes applied.');}}catch(err){toast(err.message||'Could not save this record.');}});
function validateBackup(b){if(!b||b.app!=='TraceVector'||b.version!==1||!b.state||b.state.version!==1)throw Error('Not a supported TraceVector backup.');for(const k of ['evidence','proposals','detections','activity'])if(!Array.isArray(b.state[k]))throw Error('Missing '+k+' records.');for(const k of ['objectives','scenarioProgress','evidenceUpdates','docUpdates','stig'])if(!b.state[k]||typeof b.state[k]!=='object'||Array.isArray(b.state[k]))throw Error('Invalid '+k+'.');for(const u of Object.values(b.state.docUpdates))if(!u||typeof u!=='object'||typeof u.status!=='string'||typeof u.notes!=='string')throw Error('Invalid documentation tracking.');for(const v of Object.values(b.state.evidenceUpdates))if(typeof v!=='string')throw Error('Invalid evidence tracking.');for(const v of Object.values(b.state.stig))if(!['Pending','In progress','Captured locally'].includes(v))throw Error('Invalid STIG status.');for(const v of Object.values(b.state.objectives))if(typeof v!=='boolean')throw Error('Invalid objective status.');if(typeof b.state.notes!=='string')throw Error('Invalid journal.');for(const e of b.state.evidence)if(!e||typeof e.title!=='string'||typeof e.created!=='string')throw Error('Invalid evidence record.');for(const p of b.state.proposals)if(!p||!['title','body','type','status','created'].every(k=>typeof p[k]==='string'))throw Error('Invalid proposal record.');for(const d of b.state.detections)if(!d||!['title','spl','technique'].every(k=>typeof d[k]==='string'))throw Error('Invalid detection record.');for(const a of b.state.activity)if(!a||typeof a.text!=='string')throw Error('Invalid activity record.');for(const s of Object.values(b.state.scenarioProgress))if(!Number.isInteger(s)||s<0||s>3)throw Error('Invalid scenario progress.');if(!Array.isArray(b.files)||b.files.some(f=>!f||typeof f.id!=='string'||typeof f.name!=='string'||typeof f.mime!=='string'||typeof f.data!=='string'||!/^data:(image\/(png|jpeg|webp)|text\/[\w.+-]+|application\/(pdf|json|octet-stream));base64,[A-Za-z0-9+/=]*$/.test(f.data)))throw Error('Invalid evidence attachment.');if(b.state.evidence.some(e=>e.fileId&&!b.files.some(f=>f.id===e.fileId)))throw Error('An evidence attachment is missing.');if(JSON.stringify(b.state).length>3*1024*1024)throw Error('Tracking data exceeds the local storage budget.');}
async function applyImport(){try{const b=window.pendingBackup;if(!b)return;validateBackup(b);for(const f of b.files)await dbPut(f);localStorage.setItem(KEY,JSON.stringify(b.state));state={...defaults(),...b.state};delete window.pendingBackup;document.getElementById('modal').close();currentScenario=null;render();toast('Workspace restored in this browser.');}catch(err){toast('Import failed: '+err.message);}}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!document.getElementById('modal').open)searchModal();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(next!==page){currentScenario=null;page=next;render();}});
render();
